USE football_admin_bench_20261017_a1;
ANALYZE TABLE team,player,`match`,match_result,goal_record;
SELECT 'team' AS tbl,COUNT(*) AS rows_exact FROM team UNION ALL SELECT 'player',COUNT(*) FROM player UNION ALL SELECT 'match',COUNT(*) FROM `match` UNION ALL SELECT 'match_result',COUNT(*) FROM match_result UNION ALL SELECT 'goal_record',COUNT(*) FROM goal_record;
SHOW INDEX FROM match_result;
SHOW CREATE TABLE match_result;
EXPLAIN FORMAT=TRADITIONAL SELECT m.*,ht.name AS home_team_name,at.name AS away_team_name,mr.home_score,mr.away_score,mr.referee FROM `match` m LEFT JOIN team ht ON m.home_team_id=ht.id LEFT JOIN team at ON m.away_team_id=at.id LEFT JOIN match_result mr ON m.id=mr.match_id WHERE m.deleted=0 ORDER BY m.match_time DESC LIMIT 0,10;
EXPLAIN FORMAT=TRADITIONAL SELECT p.id AS player_id,p.name AS player_name,t.name AS team_name,COUNT(g.id) AS goal_count FROM player p LEFT JOIN goal_record g ON p.id=g.player_id LEFT JOIN team t ON p.team_id=t.id WHERE p.deleted=0 AND g.deleted=0 GROUP BY p.id,p.name,t.name ORDER BY goal_count DESC;
EXPLAIN FORMAT=TRADITIONAL SELECT team_id,team_name,COUNT(*) AS played,SUM(CASE WHEN is_home=1 AND home_score>away_score THEN 1 WHEN is_home=0 AND away_score>home_score THEN 1 ELSE 0 END) AS won,SUM(CASE WHEN home_score=away_score THEN 1 ELSE 0 END) AS drawn,SUM(CASE WHEN is_home=1 AND home_score<away_score THEN 1 WHEN is_home=0 AND away_score<home_score THEN 1 ELSE 0 END) AS lost,SUM(CASE WHEN is_home=1 THEN home_score ELSE away_score END) AS goals_for,SUM(CASE WHEN is_home=1 THEN away_score ELSE home_score END) AS goals_against,(SUM(CASE WHEN is_home=1 THEN home_score ELSE away_score END)-SUM(CASE WHEN is_home=1 THEN away_score ELSE home_score END)) AS goal_difference,(SUM(CASE WHEN is_home=1 AND home_score>away_score THEN 3 WHEN is_home=0 AND away_score>home_score THEN 3 ELSE 0 END)+SUM(CASE WHEN home_score=away_score THEN 1 ELSE 0 END)) AS points FROM (SELECT m.home_team_id AS team_id,ht.name AS team_name,1 AS is_home,mr.home_score,mr.away_score FROM `match` m JOIN team ht ON m.home_team_id=ht.id JOIN match_result mr ON m.id=mr.match_id WHERE m.status IN ('finished','ended') AND m.deleted=0 UNION ALL SELECT m.away_team_id AS team_id,at.name AS team_name,0 AS is_home,mr.home_score,mr.away_score FROM `match` m JOIN team at ON m.away_team_id=at.id JOIN match_result mr ON m.id=mr.match_id WHERE m.status IN ('finished','ended') AND m.deleted=0) AS team_matches GROUP BY team_id,team_name ORDER BY points DESC,goal_difference DESC,goals_for DESC;
